export const SOURCE = "#!/usr/bin/env bash\n# Fixture for graph-in-pane: a small pairing script.\n. ./lib.sh\n\nscan() {\n  bluetoothctl scan on\n}\n\npick() {\n  local n\n  n=$(echo \"$1\" | wc -l)\n  case $n in\n    0) exit 3 ;;\n    1) printf '%s\\n' \"$1\" ;;\n    *)\n      echo \"pick one\"\n      read -r choice\n      printf '%s\\n' \"$choice\"\n      ;;\n  esac\n  return 0\n}\n\nscan\npick \"$(bluetoothctl devices)\"\nexit 0\n"
